-- Base de l'app « Mes plats et repas »
-- 1) Remplace les deux e-mails ci-dessous par le tien et celui de ta conjointe.
-- 2) Colle tout ce fichier dans Supabase > SQL Editor > New query, puis clique sur Run.

create table if not exists public.app_state (
  id text primary key,
  data jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);

alter table public.app_state enable row level security;

drop policy if exists "foyer" on public.app_state;
create policy "foyer" on public.app_state
  for all to authenticated
  using ((auth.jwt() ->> 'email') in ('TON_EMAIL@exemple.fr', 'EMAIL_CONJOINTE@exemple.fr'))
  with check ((auth.jwt() ->> 'email') in ('TON_EMAIL@exemple.fr', 'EMAIL_CONJOINTE@exemple.fr'));

-- Mises à jour en direct entre vos deux téléphones
alter publication supabase_realtime add table public.app_state;

